const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const date = '2018-02-03';
  const startDate = ee.Date(date);
  const endDate = startDate.advance(1, 'day'); // Include the full day

  // Load country boundaries
  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
  const vietnam = countries.filter(ee.Filter.eq('ADM0_NAME', 'Viet Nam'));
  const myanmar = countries.filter(ee.Filter.eq('ADM0_NAME', 'Myanmar'));

  if (vietnam.size().getInfo() === 0 || myanmar.size().getInfo() === 0) {
    console.log("Could not find country boundaries for Vietnam or Myanmar.");
    console.log("C3"); // Calculation failure due to missing country data
    return;
  }

  // 2. Data Acquisition & Check
  const fireCollection = ee.ImageCollection('FIRMS/VNP14IMGTDL_NRT/VNP14IMGTDL_NRT_VIIRS_375m_DAILY')
    .filterDate(startDate, endDate);

  const collectionSize = await fireCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log(`No VIIRS fire images found for ${date}.`);
    console.log("C1");
    return;
  }

  // Use the first image for the day, as it's daily composite
  const fireImage = fireCollection.first();

  // Function to count active fires for a given country geometry
  const countActiveFires = async (countryName, countryGeom) => {
    // Filter for nominal or high confidence fires (confidence >= 1)
    // The 'confidence' band has values: 0 = low, 1 = nominal, 2 = high
    const fires = fireImage.select('confidence').gte(1)
      .updateMask(fireImage.select('confidence').gte(1)) // Mask out non-fire pixels
      .clip(countryGeom);

    // Get the total number of fire pixels
    // Use a large scale (e.g., 375m original resolution, but reduceRegion requires larger)
    // Use a scale that's appropriate for counting objects, maybe slightly larger than native.
    // MaxPixels is important for large areas.
    const fireCount = await fires.reduceRegion({
      reducer: ee.Reducer.sum(), // Sum the masked pixels (where confidence >= 1)
      geometry: countryGeom,
      scale: 1000, // 1 km scale for reduction to avoid memory issues, original is 375m
      maxPixels: 1e9
    }).get('confidence').getInfo();

    // The result could be null if no pixels within the region satisfy the condition (e.g., no fires)
    // Or it could be 0 if there are pixels but none meet confidence threshold.
    // If it's null, convert to 0 for comparison.
    return fireCount === null ? 0 : fireCount;
  };

  // Calculate fire counts
  const vietnamFireCount = await countActiveFires('Vietnam', vietnam.geometry());
  const myanmarFireCount = await countActiveFires('Myanmar', myanmar.geometry());

  if (vietnamFireCount === null || myanmarFireCount === null) {
    console.log("Error during fire count calculation (returned null).");
    console.log("C3");
    return;
  }

  // 3. Check for C2: No Valid Pixels (after confidence filtering)
  // If both counts are 0, it means no valid fires were detected in either country.
  // This is a valid scenario and should lead to 'No' (B). C2 is for when *all* pixels are masked, not just those meeting a condition.
  // The fire collection was checked for existence; `countActiveFires` handles the case where there are no fires.

  // 4. Calculation and Comparison
  console.log(`Vietnam active fire detections on ${date}: ${vietnamFireCount}`);
  console.log(`Myanmar active fire detections on ${date}: ${myanmarFireCount}`);

  if (vietnamFireCount > myanmarFireCount) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No (or equal)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
